ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: payload.id,
  error: {
    code: -32601,
    message: "Method not found: " ++ payload.method
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: payload.id,
  result: {
    tools: [
      {
        name: "orchestrate-employee-onboarding",
        description: "Complete employee onboarding orchestration including profile creation, asset allocation, and notifications",
        inputSchema: {
          type: "object",
          properties: {
            firstName: { type: "string", description: "Employee first name" },
            lastName: { type: "string", description: "Employee last name" },
            email: { type: "string", description: "Employee email address" },
            phone: { type: "string", description: "Employee phone number" },
            department: { type: "string", description: "Department name" },
            position: { type: "string", description: "Job position/title" },
            startDate: { type: "string", description: "Start date (YYYY-MM-DD format)" },
            salary: { type: "number", description: "Annual salary" },
            manager: { type: "string", description: "Manager name" },
            managerEmail: { type: "string", description: "Manager email address" },
            companyName: { type: "string", description: "Company name" },
            assets: { type: "array", items: { type: "string" }, description: "List of assets to allocate" }
          },
          required: ["firstName", "lastName", "email"]
        }
      },
      {
        name: "get-onboarding-status",
        description: "Retrieve the current status of an employee onboarding process",
        inputSchema: {
          type: "object",
          properties: {
            employeeId: { type: "string", description: "Employee ID" },
            email: { type: "string", description: "Employee email address" }
          }
        }
      },
      {
        name: "retry-failed-step",
        description: "Retry a specific failed step in the employee onboarding process",
        inputSchema: {
          type: "object",
          properties: {
            employeeId: { type: "string", description: "Employee ID" },
            step: { type: "string", enum: ["profile-creation", "asset-allocation", "welcome-email", "asset-notification", "onboarding-complete"] }
          },
          required: ["employeeId", "step"]
        }
      },
      {
        name: "check-system-health",
        description: "Check the health status of all employee onboarding system components",
        inputSchema: { type: "object", properties: {} }
      },
      {
        name: "ai-reasoning",
        description: "Use AI reasoning to understand natural language requests and suggest onboarding actions",
        inputSchema: {
          type: "object",
          properties: {
            prompt: { type: "string", description: "Natural language request for employee onboarding assistance" }
          },
          required: ["prompt"]
        }
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id,
  result: {
    content: [
      {
        type: "text",
        text: "Employee onboarding orchestration completed successfully!\n\n" ++ write(payload, "application/json", {"indent": true})
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id default null,
  error: {
    code: -32603,
    message: "Internal error: " ++ error.description,
    data: error.detailedDescription
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id,
  result: {
    content: [
      {
        type: "text",
        text: "Onboarding status retrieved:\n\n" ++ write(payload, "application/json", {"indent": true})
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id,
  result: {
    content: [
      {
        type: "text",
        text: "Step retry initiated:\n\n" ++ write(payload, "application/json", {"indent": true})
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id,
  result: {
    content: [
      {
        type: "text",
        text: "System health check result:\n\n" ++ write(payload, "application/json", {"indent": true})
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.originalPayload.id,
  result: {
    content: [
      {
        type: "text",
        text: "AI Reasoning Result:\n\n" ++ write(payload, "application/json", {"indent": true})
      }
    ]
  }
}
